using Flurl.Http;
using System.Collections.Generic;

var loginResponse = await "https://metasys-server.example.com/api/v6/login"
    .PostJsonAsync(new
        {
            username = "jane-doe",
            password = "strongPassword"
        })
    .ReceiveJson<Dictionary<string,object>>();
var accessToken = loginResponse["accessToken"];

import axios from 'axios';

const axiosClient = axios.create({
  baseURL: 'https://metasys-server.example.com/api/v6'
});

const loginResponse = await axiosClient.post('login', {
  username: 'jane-doe',
  password: 'strongPassword'
}, {
  headers: {
    'Content-Type': 'application/json'
  }
});

const accessToken = loginResponse.data.accessToken;

// You'll use `axiosClient` and `accessToken` in most
// other axios code examples

HttpRequest loginRequest = HttpRequest.newBuilder()
    .uri(URI.create("https://metasys-server.example.com/api/v6/login"))
    .header("Content-Type", "application/json")
    .method("POST", HttpRequest.BodyPublishers.ofString("{\"username\":\"jane-doe\",\"password\":\"strongPassword\"}"))
    .build();
HttpResponse<String> loginResponse = HttpClient.newHttpClient().send(loginRequest, HttpResponse.BodyHandlers.ofString());
String responseBody = loginResponse.body();
JSONObject jsonResponse = new JSONObject(responseBody);
String accessToken = jsonResponse.getString("accessToken");

// See CSharp + Flurl example for "authentication | Request access token"
// to see how to import Flurl and set `accessToken` variable
var response = await "https://metasys-server.example.com/api/v6/refreshToken"
    .WithHeader("Authorization", $"Bearer {accessToken}")
    .GetAsync();

# To set $accessToken see the Powershell example of "authentication | Request a token"
